#include "stdafx.h"#include "HcdElementBase.h"struct SLTCH_P{#include "PrivateVars/LTCH.h"};class KLTCH : public KHcdElementBase  , protected SLTCH_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _LTCH("LTCH", KLTCH::Create);IHcdElement *KLTCH::Create(){  return new KLTCH;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KLTCH, 3 )void KLTCH::InitParm(){#include "PrivateVars/LTCH.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KLTCH::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KLTCH::StepCalc( SStepCalcParams &params ){  if( U )    OUTR0 = 0;  if( L )    OUTR0 = 1;}